GITA_CH[12] = {"num": 12, "deva": "भक्तियोग", "verses": 20, "names": {"en": "Bhakti Yoga", "ne": "भक्ति योग", "hi": "भक्ति योग"}, "subs": {"en": "The path of devotion", "ne": "भक्तिको मार्ग", "hi": "भक्ति का मार्ग"}, "themes": [{"range": "12.01–12.05", "titles": {"en": "Devotion or the unmanifest: the choice of path", "ne": "भक्ति वा अव्यक्त: मार्गको छनोट", "hi": "भक्ति या अव्यक्त: मार्ग का चुनाव"}, "descs": {"en": "Arjuna compares devotion with the unmanifest path. Both reach Kṛṣṇa, but faith-filled personal devotion is praised; the unmanifest is harder for the embodied.", "ne": "अर्जुनले भक्ति र अव्यक्तको मार्ग तुलना गर्छन्। दुवैले कृष्णलाई पाउँछन्, तर श्रद्धापूर्ण भक्ति श्रेष्ठ भनिन्छ; देहीलाई अव्यक्तको मार्ग कठिन छ।", "hi": "अर्जुन भक्ति और अव्यक्त के मार्ग की तुलना करता है। दोनों कृष्ण तक पहुँचते हैं, पर श्रद्धापूर्ण भक्ति प्रशंसित है; देही के लिए अव्यक्त कठिन है।"}, "parts": [{"range": "12.01–12.01", "titles": {"en": "Which knows yoga better?", "ne": "कसले योग राम्ररी जान्दछ?", "hi": "कौन योग बेहतर जानता है?"}, "descs": {"en": "Arjuna asks: of devotees who worship Kṛṣṇa with form and those who worship the imperishable unmanifest, who knows yoga better?", "ne": "अर्जुन सोध्छन्: रूपसहित कृष्णलाई भज्ने र अक्षर अव्यक्तलाई भज्ने भक्तहरूमध्ये को योगमा उत्तम?", "hi": "अर्जुन पूछते हैं: रूप सहित कृष्ण को भजने वाले और अक्षर अव्यक्त को भजने वाले भक्तों में योग में कौन श्रेष्ठ है?"}, "sutras": [{"n": "12.01", "d": "अर्जुन उवाच । एवं सततयुक्ता ये भक्तास्त्वां पर्युपासते । ये चाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः", "t": "arjuna uvāca । evaṃ satatayuktā ye bhaktāstvāṃ paryupāsate । ye cāpyakṣaramavyaktaṃ teṣāṃ ke yogavittamāḥ", "flow": [{"k": "s", "d": "अर्जुन उवाच।", "t": "arjuna uvāca", "words": [["अर्जुनः", "arjunaḥ", "Arjuna", "अर्जुनले", "अर्जुन"], ["उवाच", "uvāca", "said", "भने", "बोले"]]}, {"k": "p", "d": "एवं सततयुक्ता ये", "t": "evaṃ satatayuktā ye", "n": 8, "words": [["एवम्", "evam", "thus", "यसरी", "इस प्रकार"], ["सततयुक्ताः", "satatayuktāḥ", "ever united", "सधैं युक्त", "सदा युक्त"], ["ये", "ye", "who", "जो", "जो"]]}, {"k": "p", "d": "भक्तास्त्वां पर्युपासते", "t": "bhaktāstvāṃ paryupāsate", "n": 8, "words": [["भक्ताः", "bhaktāḥ", "devotees", "भक्तहरू", "भक्त"], ["त्वाम्", "tvām", "you", "तिमीलाई", "तुम्हें"], ["पर्युपासते", "paryupāsate", "worship", "पूजा गर्छन्", "पूजा करते हैं"]]}, {"k": "p", "d": "ये चाप्यक्षरमव्यक्तं", "t": "ye cāpyakṣaramavyaktaṃ", "n": 8, "words": [["ये", "ye", "who", "जो", "जो"], ["च", "ca", "and", "र", "और"], ["अपि", "api", "also", "पनि", "भी"], ["अक्षरम्", "akṣaram", "the imperishable", "अक्षर", "अक्षर"], ["अव्यक्तम्", "avyaktam", "the unmanifest", "अव्यक्त", "अव्यक्त"]]}, {"k": "p", "d": "तेषां के योगवित्तमाः", "t": "teṣāṃ ke yogavittamāḥ", "n": 8, "words": [["तेषाम्", "teṣām", "of them", "तिनीहरूको", "उनका"], ["के", "ke", "which", "कुन", "कौन-से"], ["योगवित्तमाः", "yogavittamāḥ", "the best knowers of yoga", "योगका उत्तम ज्ञाता", "योग के उत्तम ज्ञाता"]]}], "lits": {"en": "Arjuna said: Those devotees who, ever united, worship you — and those who worship the imperishable unmanifest — which of these are the better knowers of yoga?", "ne": "अर्जुनले भने: सधैं युक्त भएर तपाईंको पूजा गर्ने भक्तहरू — र अविनाशी अव्यक्तको पूजा गर्नेहरू — यीमध्ये कुन योगका राम्रो ज्ञाता हुन्?", "hi": "अर्जुन ने कहा: सदा युक्त होकर आपकी पूजा करने वाले भक्त — और अविनाशी अव्यक्त की पूजा करने वाले — इनमें से कौन योग के बेहतर ज्ञाता हैं?"}, "paras": {"en": "Arjuna asks: “Which are the greater yogis — those who worship you with devotion, or those who worship the formless, imperishable Absolute?”", "ne": "अर्जुन सोध्छन्: “कुन ठूला योगी हुन् — भक्तिले तपाईंको पूजा गर्ने, वा निराकार, अविनाशी परमात्माको पूजा गर्ने?”", "hi": "अर्जुन पूछते हैं: “कौन बड़े योगी हैं — भक्ति से आपकी पूजा करने वाले, या निराकार, अविनाशी परमात्मा की पूजा करने वाले?”"}}]}, {"range": "12.02–12.02", "titles": {"en": "Those ever-united in me are best in yoga", "ne": "ममा नित्ययुक्त नै श्रेष्ठ योगी", "hi": "मुझमें नित्ययुक्त ही श्रेष्ठ योगी"}, "descs": {"en": "Kṛṣṇa: those who fix their minds on him and worship with supreme faith are, in his view, the best.", "ne": "कृष्ण: उनमा मन लगाई परम श्रद्धाले भज्ने उनको दृष्टिमा सर्वश्रेष्ठ हुन्।", "hi": "कृष्ण: उनमें मन लगाकर परम श्रद्धा से भजने वाले उनकी दृष्टि में सर्वश्रेष्ठ हैं।"}, "sutras": [{"n": "12.02", "d": "श्रीभगवानुवाच । मय्यावेश्य मनो ये मां नित्ययुक्ता उपासते । श्रद्धया परयोपेताः ते मे युक्ततमा मताः", "t": "śrībhagavānuvāca । mayyāveśya mano ye māṃ nityayuktā upāsate । śraddhayā parayopetāḥ te me yuktatamā matāḥ", "flow": [{"k": "s", "d": "श्रीभगवानुवाच।", "t": "śrībhagavānuvāca", "words": [["श्रीभगवान्", "śrībhagavān", "the Blessed Lord", "श्रीभगवान्ले", "श्रीभगवान्"], ["उवाच", "uvāca", "said", "भन्नुभयो", "बोले"]]}, {"k": "p", "d": "मय्यावेश्य मनो ये मां", "t": "mayyāveśya mano ye māṃ", "n": 8, "words": [["मयि", "mayi", "on me", "ममा", "मुझमें"], ["आवेश्य", "āveśya", "having fixed", "स्थिर गरेर", "स्थिर करके"], ["मनः", "manaḥ", "the mind", "मन", "मन"], ["ये", "ye", "who", "जो", "जो"], ["माम्", "mām", "me", "मलाई", "मुझे"]]}, {"k": "p", "d": "नित्ययुक्ता उपासते", "t": "nityayuktā upāsate", "n": 8, "words": [["नित्ययुक्ताः", "nityayuktāḥ", "ever united", "सधैं युक्त", "सदा युक्त"], ["उपासते", "upāsate", "worship", "उपासना गर्छन्", "उपासना करते हैं"]]}, {"k": "p", "d": "श्रद्धया परयोपेताः", "t": "śraddhayā parayopetāḥ", "n": 8, "words": [["श्रद्धया", "śraddhayā", "with faith", "श्रद्धासाथ", "श्रद्धा से"], ["परया", "parayā", "supreme", "परम", "परम"], ["उपेताः", "upetāḥ", "endowed", "युक्त", "युक्त"]]}, {"k": "p", "d": "ते मे युक्ततमा मताः", "t": "te me yuktatamā matāḥ", "n": 8, "words": [["ते", "te", "they", "तिनीहरू", "वे"], ["मे", "me", "in my", "मेरो", "मेरा"], ["युक्ततमाः", "yuktatamāḥ", "the most yoked", "सबैभन्दा युक्त", "सबसे युक्त"], ["मताः", "matāḥ", "deemed", "मानिन्छन्", "माने जाते हैं"]]}], "lits": {"en": "The Blessed Lord said: Those who, fixing their minds on me, ever united, worship me with supreme faith — them I deem the most yoked.", "ne": "श्रीभगवान्ले भन्नुभयो: जसले मन ममा लगाएर, सधैं युक्त भएर, परम श्रद्धाले मेरो पूजा गर्छन् — तिनैलाई म सबैभन्दा युक्त मान्छु।", "hi": "श्री भगवान् ने कहा: जो मन मुझ में लगाकर, सदा युक्त होकर, परम श्रद्धा से मेरी पूजा करते हैं — उन्हें ही मैं सबसे युक्त मानता हूँ।"}, "paras": {"en": "Kṛṣṇa said: “Those who fix their minds on me, ever devoted, worshipping me with supreme faith — they are the greatest yogis in my view.”", "ne": "कृष्णले भन्नुभयो: “जसले मन ममा राखेर, सधैं समर्पित भएर, परम श्रद्धाले मेरो पूजा गर्छन् — मेरो दृष्टिमा तिनै महान् योगी हुन्।”", "hi": "कृष्ण ने कहा: “जो मन मुझ पर रखकर, सदा समर्पित होकर, परम श्रद्धा से मेरी पूजा करते हैं — मेरी दृष्टि में वे ही महान् योगी हैं।”"}}]}, {"range": "12.03–12.03", "titles": {"en": "Some worship the imperishable unmanifest", "ne": "कोही अक्षर अव्यक्तको उपासना गर्छन्", "hi": "कुछ अक्षर अव्यक्त की उपासना करते हैं"}, "descs": {"en": "Others worship the imperishable, indefinable, unmanifest, all-pervading and unchanging…", "ne": "अरूले अक्षर, अनिर्देश्य, अव्यक्त, सर्वव्यापी र अचललाई उपासना गर्छन्…", "hi": "अन्य अक्षर, अनिर्देश्य, अव्यक्त, सर्वव्यापी और अचल की उपासना करते हैं…"}, "sutras": [{"n": "12.03", "d": "ये त्वक्षरमनिर्देश्यं अव्यक्तं पर्युपासते । सर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम्", "t": "ye tvakṣaramanirdeśyaṃ avyaktaṃ paryupāsate । sarvatragamacintyaṃ ca kūṭasthamacalaṃ dhruvam", "flow": [{"k": "p", "d": "ये त्वक्षरमनिर्देश्यं", "t": "ye tvakṣaramanirdeśyaṃ", "n": 8, "words": [["ये", "ye", "those who", "जो", "जो"], ["तु", "tu", "but", "तर", "पर"], ["अक्षरम्", "akṣaram", "the imperishable", "अक्षर", "अक्षर"], ["अनिर्देश्यम्", "anirdeśyam", "the indefinable", "अवर्णनीय", "अवर्णनीय"]]}, {"k": "p", "d": "अव्यक्तं पर्युपासते", "t": "avyaktaṃ paryupāsate", "n": 8, "words": [["अव्यक्तम्", "avyaktam", "the unmanifest", "अव्यक्त", "अव्यक्त"], ["पर्युपासते", "paryupāsate", "worship", "पूजा गर्छन्", "पूजा करते हैं"]]}, {"k": "p", "d": "सर्वत्रगमचिन्त्यं च", "t": "sarvatragamacintyaṃ ca", "n": 8, "words": [["सर्वत्रगम्", "sarvatragam", "all-pervading", "सर्वव्यापी", "सर्वव्यापी"], ["अचिन्त्यम्", "acintyam", "unthinkable", "अचिन्त्य", "अचिन्त्य"], ["च", "ca", "and", "र", "और"]]}, {"k": "p", "d": "कूटस्थमचलं ध्रुवम्", "t": "kūṭasthamacalaṃ dhruvam", "n": 8, "words": [["कूटस्थम्", "kūṭastham", "unchanging", "अचल", "अचल"], ["अचलम्", "acalam", "immovable", "अचल", "अचल"], ["ध्रुवम्", "dhruvam", "eternal", "नित्य", "नित्य"]]}], "lits": {"en": "But those who worship the imperishable, the indefinable, the unmanifest — the all-pervading, unthinkable, unchanging, immovable, eternal —", "ne": "तर जो अविनाशी, अवर्णनीय, अव्यक्त — सर्वव्यापी, अचिन्त्य, अपरिवर्तनीय, अचल, नित्य — को पूजा गर्छन्,", "hi": "किन्तु जो अविनाशी, अवर्णनीय, अव्यक्त — सर्वव्यापी, अचिन्त्य, अपरिवर्तनीय, अचल, नित्य — की पूजा करते हैं,"}, "paras": {"en": "“But those who worship the unmanifest — indefinable, all-pervading, unthinkable, immutable, eternal —”", "ne": "अरू छन्, जो नदेखिनेलाई पुज्छन् — जसलाई शब्दले भ्याउँदैन, जो जताततै छ, जसलाई सोचले छुन सक्दैन, जो न बदलिन्छ न हल्लिन्छ, सधैँको।", "hi": "और कुछ लोग उस निराकार की उपासना करते हैं — जिसे शब्दों में बाँधा नहीं जा सकता, जो हर जगह है, सोच से परे, कभी न बदलने वाला,"}}]}, {"range": "12.04–12.04", "titles": {"en": "They too reach me", "ne": "तिनीहरू पनि ममै आइपुग्छन्", "hi": "वे भी मुझ तक पहुँचते हैं"}, "descs": {"en": "…controlling the senses, even-minded and glad in all beings’ welfare; they too reach him.", "ne": "…इन्द्रिय वशमा राखी, सम बुद्धिले, सबै प्राणीको हितमा रमाउँदै; ती पनि उनैलाई पाउँछन्।", "hi": "…इंद्रियों को वश में रखकर, सम बुद्धि से, सब प्राणियों के हित में रमते हुए; वे भी उन्हीं को पाते हैं।"}, "sutras": [{"n": "12.04", "d": "सन्नियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः । ते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः", "t": "sanniyamyendriyagrāmaṃ sarvatra samabuddhayaḥ । te prāpnuvanti māmeva sarvabhūtahite ratāḥ", "flow": [{"k": "p", "d": "सन्नियम्येन्द्रियग्रामं", "t": "sanniyamyendriyagrāmaṃ", "n": 8, "words": [["सन्नियम्य", "sanniyamya", "having controlled", "नियन्त्रण गरेर", "नियंत्रित करके"], ["इन्द्रियग्रामम्", "indriyagrāmam", "the whole host of senses", "इन्द्रिय-समूह", "इन्द्रिय-समूह"]]}, {"k": "p", "d": "सर्वत्र समबुद्धयः", "t": "sarvatra samabuddhayaḥ", "n": 8, "words": [["सर्वत्र", "sarvatra", "everywhere", "सर्वत्र", "सर्वत्र"], ["समबुद्धयः", "samabuddhayaḥ", "of equal mind", "समान बुद्धि भएका", "समान बुद्धि वाले"]]}, {"k": "p", "d": "ते प्राप्नुवन्ति मामेव", "t": "te prāpnuvanti māmeva", "n": 8, "words": [["ते", "te", "they", "तिनीहरू", "वे"], ["प्राप्नुवन्ति", "prāpnuvanti", "reach", "पुग्छन्", "पहुँचते हैं"], ["माम्", "mām", "me", "मलाई", "मुझे"], ["एव", "eva", "indeed", "नै", "ही"]]}, {"k": "p", "d": "सर्वभूतहिते रताः", "t": "sarvabhūtahite ratāḥ", "n": 8, "words": [["सर्वभूतहिते", "sarvabhūtahite", "in the welfare of all beings", "सबै प्राणीको हितमा", "सब प्राणियों के हित में"], ["रताः", "ratāḥ", "rejoicing", "रम्ने", "रमने वाले"]]}], "lits": {"en": "— controlling all the senses, of equal mind everywhere, rejoicing in the welfare of all beings — they too reach me.", "ne": "— सबै इन्द्रियहरूलाई संयत गरेर, सर्वत्र समान मन भएर, सबै प्राणीको हितमा रमेर — तिनीहरू पनि मकहाँ आउँछन्।", "hi": "— सब इन्द्रियों को संयत करके, सर्वत्र समान मन से, सब प्राणियों के हित में रमकर — वे भी मुझे प्राप्त होते हैं।"}, "paras": {"en": "“— who restrain the senses, see all equally, and delight in the good of all beings — they also reach me.”", "ne": "“— जसले इन्द्रियलाई रोकेर, सबैलाई समान देखेर, सबै प्राणीको हितमा रम्छन् — तिनीहरू पनि मकहाँ पुग्छन्।”", "hi": "“— जो इन्द्रियों को रोककर, सबको समान देखकर, सब प्राणियों के हित में रमते हैं — वे भी मुझ तक पहुँचते हैं।”"}}]}, {"range": "12.05–12.05", "titles": {"en": "Greater is the toil of those set on the unmanifest", "ne": "अव्यक्तमा लागेकाको क्लेश अधिक", "hi": "अव्यक्त में लगे लोगों का क्लेश अधिक"}, "descs": {"en": "But the toil of those set on the unmanifest is greater, for that goal is hard for embodied beings to reach.", "ne": "तर अव्यक्तमा चित्त लगाउनेको श्रम अझ बढी हुन्छ, किनकि देहधारीका लागि त्यो गति पाउन कठिन छ।", "hi": "पर अव्यक्त में चित्त लगाने वालों का श्रम अधिक है, क्योंकि देहधारी के लिए वह गति पाना कठिन है।"}, "sutras": [{"n": "12.05", "d": "क्लेशोऽधिकतरस्तेषां अव्यक्तासक्तचेतसाम् । अव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते", "t": "kleśo’dhikatarasteṣāṃ avyaktāsaktacetasām । avyaktā hi gatirduḥkhaṃ dehavadbhiravāpyate", "flow": [{"k": "p", "d": "क्लेशोऽधिकतरस्तेषां", "t": "kleśo’dhikatarasteṣāṃ", "n": 8, "words": [["क्लेशः", "kleśaḥ", "toil", "कष्ट", "कष्ट"], ["अधिकतरः", "adhikataraḥ", "greater", "अझ ठूलो", "और बड़ा"], ["तेषाम्", "teṣām", "of those", "तिनीहरूको", "उनका"]]}, {"k": "p", "d": "अव्यक्तासक्तचेतसाम्", "t": "avyaktāsaktacetasām", "n": 8, "words": [["अव्यक्त", "avyakta", "to the unmanifest", "अव्यक्तलाई", "अव्यक्त को"], ["आसक्त", "āsakta", "attached", "आसक्त", "आसक्त"], ["चेतसाम्", "cetasām", "of minds", "जसका मन", "जिनके मन"]]}, {"k": "p", "d": "अव्यक्ता हि गतिर्दुःखं", "t": "avyaktā hi gatirduḥkhaṃ", "n": 8, "words": [["अव्यक्ता", "avyaktā", "the unmanifest", "अव्यक्त", "अव्यक्त"], ["हि", "hi", "indeed", "नै", "ही"], ["गतिः", "gatiḥ", "the path", "गति", "गति"], ["दुःखम्", "duḥkham", "hard", "गाह्रो", "कठिन"]]}, {"k": "p", "d": "देहवद्भिरवाप्यते", "t": "dehavadbhiravāpyate", "n": 8, "words": [["देहवद्भिः", "dehavadbhiḥ", "by embodied beings", "देहधारीहरूद्वारा", "देहधारियों से"], ["अवाप्यते", "avāpyate", "is attained", "प्राप्त गरिन्छ", "प्राप्त होता है"]]}], "lits": {"en": "Greater is the toil of those whose minds are attached to the unmanifest; the unmanifest is hard to attain by embodied beings.", "ne": "जसका मन अव्यक्तमा आसक्त छन्, तिनको परिश्रम बढी हुन्छ; देहधारीहरूका निम्ति अव्यक्त पुग्न गाह्रो छ।", "hi": "जिनके मन अव्यक्त में आसक्त हैं, उनका परिश्रम अधिक है; देहधारियों के लिए अव्यक्त की प्राप्ति कठिन है।"}, "paras": {"en": "“But their struggle is greater, for the formless Absolute is hard to reach for those who dwell in bodies.”", "ne": "“तर तिनको संघर्ष ठूलो छ, किनकि निराकार परमात्मा शरीरमा बस्नेहरूका निम्ति पुग्न कठिन छ।”", "hi": "“किन्तु उनका संघर्ष बड़ा है, क्योंकि निराकार परमात्मा शरीर में रहने वालों के लिए दुर्लभ है।”"}}]}]}, {"range": "12.06–12.08", "titles": {"en": "Surrender and fix the heart on me", "ne": "समर्पण गरेर मन-बुद्धि ममा राख", "hi": "समर्पण करके मन-बुद्धि मुझमें रखो"}, "descs": {"en": "Kṛṣṇa swiftly delivers those who dedicate action and meditate on him. Fix mind and intellect in him: the promise is to dwell in him.", "ne": "कर्म समर्पण गरेर ध्यान गर्नेहरूलाई कृष्णले मृत्युसंसारबाट शीघ्र उद्धार गर्नुहुन्छ। मन र बुद्धि उहाँमा राख; उहाँमै निवास गर्ने प्रतिज्ञा छ।", "hi": "कर्म समर्पित कर ध्यान करने वालों को कृष्ण मृत्यु-संसार से शीघ्र उद्धारते हैं। मन और बुद्धि उनमें रखो; उन्हीं में निवास का आश्वासन है।"}, "parts": [{"range": "12.06–12.06", "titles": {"en": "Those who surrender all actions to me", "ne": "सबै कर्म ममा अर्पण गर्नेहरू", "hi": "सब कर्म मुझमें अर्पित करने वाले"}, "descs": {"en": "Those who surrender all actions to him and worship him with undivided meditation…", "ne": "जसले सबै कर्म उनमा अर्पण गरी अनन्य ध्यानले उनको उपासना गर्छन्…", "hi": "जो सब कर्म उन्हें अर्पित करके अनन्य ध्यान से उनकी उपासना करते हैं…"}, "sutras": [{"n": "12.06", "d": "ये तु सर्वाणि कर्माणि मयि सन्न्यस्य मत्पराः । अनन्येनैव योगेन मां ध्यायन्त उपासते", "t": "ye tu sarvāṇi karmāṇi mayi sannyasya matparāḥ । ananyenaiva yogena māṃ dhyāyanta upāsate", "flow": [{"k": "p", "d": "ये तु सर्वाणि कर्माणि", "t": "ye tu sarvāṇi karmāṇi", "n": 8, "words": [["ये", "ye", "those who", "जो", "जो"], ["तु", "tu", "but", "तर", "पर"], ["सर्वाणि", "sarvāṇi", "all", "सबै", "सब"], ["कर्माणि", "karmāṇi", "actions", "कर्महरू", "कर्म"]]}, {"k": "p", "d": "मयि सन्न्यस्य मत्पराः", "t": "mayi sannyasya matparāḥ", "n": 8, "words": [["मयि", "mayi", "in me", "ममा", "मुझमें"], ["सन्न्यस्य", "sannyasya", "having surrendered", "समर्पण गरेर", "समर्पण करके"], ["मत्पराः", "matparāḥ", "intent on me", "ममै तत्पर", "मुझ में तत्पर"]]}, {"k": "p", "d": "अनन्येनैव योगेन", "t": "ananyenaiva yogena", "n": 8, "words": [["अनन्येन", "ananyena", "undivided", "अनन्य", "अनन्य"], ["एव", "eva", "indeed", "नै", "ही"], ["योगेन", "yogena", "with yoga", "योगले", "योग से"]]}, {"k": "p", "d": "मां ध्यायन्त उपासते", "t": "māṃ dhyāyanta upāsate", "n": 8, "words": [["माम्", "mām", "me", "मलाई", "मुझे"], ["ध्यायन्तः", "dhyāyantaḥ", "meditating on", "ध्यान गर्दै", "ध्यान करते हुए"], ["उपासते", "upāsate", "worship", "उपासना गर्छन्", "उपासना करते हैं"]]}], "lits": {"en": "But those who surrender all actions to me, intent on me, worshipping me with undivided yoga and meditating on me,", "ne": "तर जसले सबै कर्म ममा अर्पण गर्छन्, ममै तत्पर भएर, अविभाजित योगले मेरो पूजा गर्छन् र मेरो ध्यान गर्छन्,", "hi": "किन्तु जो सब कर्म मुझ में अर्पण करते हैं, मुझ में ही तत्पर होकर, अविभाजित योग से मेरी पूजा करते हैं और मेरा ध्यान करते हैं,"}, "paras": {"en": "“But those who offer all their actions to me, take me as supreme, and worship me with single-minded meditation,”", "ne": "“तर जसले आफ्ना सबै कर्म मलाई अर्पण गर्छन्, मलाई परम मान्छन्, र एकाग्र ध्यानले मेरो पूजा गर्छन्,”", "hi": "“किन्तु जो अपने सब कर्म मुझे अर्पण करते हैं, मुझे परम मानते हैं, और एकाग्र ध्यान से मेरी पूजा करते हैं,”"}}]}, {"range": "12.07–12.07", "titles": {"en": "I become their deliverer from the ocean of death", "ne": "म मृत्युसागरबाट उद्धारक बन्छु", "hi": "मैं मृत्युसागर से उद्धारक बनता हूँ"}, "descs": {"en": "…he swiftly lifts out of the ocean of death and rebirth, since their minds are on him.", "ne": "…उनमा चित्त लगाएका तिनलाई उनले चाँडै मृत्यु-संसार-सागरबाट उद्धार गर्छन्।", "hi": "…उनमें चित्त लगाए उन लोगों का वे शीघ्र मृत्यु-संसार-सागर से उद्धार करते हैं।"}, "sutras": [{"n": "12.07", "d": "तेषामहं समुद्धर्ता मृत्युसंसारसागरात् । भवामि न चिरात्पार्थ मय्यावेशितचेतसाम्", "t": "teṣāmahaṃ samuddhartā mṛtyusaṃsārasāgarāt । bhavāmi na cirātpārtha mayyāveśitacetasām", "flow": [{"k": "p", "d": "तेषामहं समुद्धर्ता", "t": "teṣāmahaṃ samuddhartā", "n": 8, "words": [["तेषाम्", "teṣām", "of them", "तिनीहरूको", "उनका"], ["अहम्", "aham", "I", "म", "मैं"], ["समुद्धर्ता", "samuddhartā", "the deliverer", "उद्धारकर्ता", "उद्धारकर्ता"]]}, {"k": "p", "d": "मृत्युसंसारसागरात्", "t": "mṛtyusaṃsārasāgarāt", "n": 8, "words": [["मृत्युसंसारसागरात्", "mṛtyusaṁsārasāgarāt", "from the ocean of death and rebirth", "जन्म-मृत्युको सागरबाट", "जन्म-मृत्यु के सागर से"]]}, {"k": "p", "d": "भवामि न चिरात्पार्थ", "t": "bhavāmi na cirātpārtha", "n": 8, "words": [["भवामि", "bhavāmi", "I become", "बन्छु", "बनता हूँ"], ["न", "na", "not", "न", "नहीं"], ["चिरात्", "cirāt", "long, after a while", "लामो समयपछि", "बहुत समय बाद"], ["पार्थ", "pārtha", "O Pārtha", "हे पार्थ", "हे पार्थ"]]}, {"k": "p", "d": "मय्यावेशितचेतसाम्", "t": "mayyāveśitacetasām", "n": 8, "words": [["मयि", "mayi", "on me", "ममा", "मुझमें"], ["आवेशित", "āveśita", "fixed", "स्थिर गरिएको", "स्थिर किया हुआ"], ["चेतसाम्", "cetasām", "of those whose minds", "जसका मन", "जिनके मन"]]}], "lits": {"en": "— for them, whose minds are fixed on me, O Pārtha, I swiftly become the deliverer from the ocean of death and rebirth.", "ne": "हे पार्थ, तिनका निम्ति, जसका मन ममा टिकेका छन्, म चाँडै नै जन्म-मृत्युको सागरबाट उद्धारक बन्छु।", "hi": "— हे पार्थ, उनके लिए, जिनका मन मुझ में टिका है, मैं शीघ्र ही जन्म-मृत्यु के सागर से उद्धारक बन जाता हूँ।"}, "paras": {"en": "“— for them, whose hearts rest in me, I quickly become their saviour from the ocean of birth and death.”", "ne": "“— जसका हृदय ममा विश्राम गर्छन्, तिनका निम्ति म चाँडै जन्म-मृत्युको सागरबाट उद्धारकर्ता बन्छु।”", "hi": "“— जिनका हृदय मुझ में विश्राम करता है, उनके लिए मैं शीघ्र ही जन्म-मृत्यु के सागर से उद्धारकर्ता बन जाता हूँ।”"}}]}, {"range": "12.08–12.08", "titles": {"en": "Fix your mind on me alone", "ne": "ममै मन राख", "hi": "मुझमें ही मन लगा"}, "descs": {"en": "So Arjuna is told to fix his mind and intellect on Kṛṣṇa alone, and he will live in him.", "ne": "त्यसैले अर्जुनले मन-बुद्धि कृष्णमै लगाउनू, र उनमै बस्नेछन्।", "hi": "इसलिए अर्जुन मन-बुद्धि कृष्ण में ही लगाएँ, और वे उन्हीं में रहेंगे।"}, "sutras": [{"n": "12.08", "d": "मय्येव मन आधत्स्व मयि बुद्धिं निवेशय । निवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः", "t": "mayyeva mana ādhatsva mayi buddhiṃ niveśaya । nivasiṣyasi mayyeva ata ūrdhvaṃ na saṃśayaḥ", "flow": [{"k": "p", "d": "मय्येव मन आधत्स्व", "t": "mayyeva mana ādhatsva", "n": 8, "words": [["मयि", "mayi", "on me", "ममा", "मुझमें"], ["एव", "eva", "alone", "नै", "ही"], ["मनः", "manaḥ", "the mind", "मन", "मन"], ["आधत्स्व", "ādhatsva", "fix", "स्थिर गर", "स्थिर कर"]]}, {"k": "p", "d": "मयि बुद्धिं निवेशय", "t": "mayi buddhiṃ niveśaya", "n": 8, "words": [["मयि", "mayi", "in me", "ममा", "मुझमें"], ["बुद्धिम्", "buddhim", "the intellect", "बुद्धि", "बुद्धि"], ["निवेशय", "niveśaya", "establish", "स्थिर गर", "स्थिर कर"]]}, {"k": "p", "d": "निवसिष्यसि मय्येव", "t": "nivasiṣyasi mayyeva", "n": 8, "words": [["निवसिष्यसि", "nivasiṣyasi", "you will live", "बाँच्नेछौ", "रहोगे"], ["मयि", "mayi", "in me", "ममा", "मुझमें"], ["एव", "eva", "alone", "नै", "ही"]]}, {"k": "p", "d": "अत ऊर्ध्वं न संशयः", "t": "ata ūrdhvaṃ na saṃśayaḥ", "n": 8, "words": [["अतः", "ataḥ", "then", "त्यसैले", "इसलिए"], ["ऊर्ध्वम्", "ūrdhvam", "upwards, hereafter", "माथि", "ऊपर"], ["न", "na", "no", "न", "नहीं"], ["संशयः", "saṁśayaḥ", "doubt", "सन्देह", "सन्देह"]]}], "lits": {"en": "Fix your mind on me alone; establish your intellect in me; then you shall live in me alone — of this there is no doubt.", "ne": "केवल ममै मन लगाऊ; ममै बुद्धि स्थिर गर; तब तिमी ममै बाँच्नेछौ — यसमा कुनै सन्देह छैन।", "hi": "केवल मुझ में ही मन लगा; मुझ में ही बुद्धि स्थिर कर; तब तू मुझ में ही रहेगा — इसमें कोई सन्देह नहीं।"}, "paras": {"en": "“Rest your mind and understanding on me alone — and you will surely live in me; of this there is no doubt.”", "ne": "“आफ्नो मन र समझ केवल ममा राख — र तिमी निश्चय ममै बाँच्नेछौ; यसमा कुनै सन्देह छैन।”", "hi": "“अपना मन और समझ केवल मुझ पर रख — और तू निश्चय मुझ में ही रहेगा; इसमें कोई सन्देह नहीं।”"}}]}]}, {"range": "12.09–12.12", "titles": {"en": "A ladder of practice ending in peace", "ne": "शान्तिमा पुग्ने अभ्यासको सोपान", "hi": "शांति तक पहुँचाने वाला अभ्यास का सोपान"}, "descs": {"en": "A graded path: if concentration is difficult, practise; if that is difficult, work for Kṛṣṇa. If needed, relinquish action’s fruits: renunciation brings peace.", "ne": "सोपानयुक्त मार्ग: एकाग्रता कठिन भए अभ्यास गर; त्यो कठिन भए कृष्णका लागि कर्म गर। आवश्यक भए कर्मफल छोड; फलत्यागबाट शान्ति मिल्छ।", "hi": "सोपानयुक्त मार्ग: एकाग्रता कठिन हो तो अभ्यास करो; वह कठिन हो तो कृष्ण के लिए कर्म करो। आवश्यक हो तो कर्मफल छोड़ो; फलत्याग से शांति मिलती है।"}, "parts": [{"range": "12.09–12.09", "titles": {"en": "Then seek me by repeated practice", "ne": "अभ्यासयोगले मलाई खोज", "hi": "अभ्यासयोग से मुझे खोज"}, "descs": {"en": "If he cannot hold his mind steady, he should seek him by repeated practice.", "ne": "चित्त स्थिर गर्न नसके अभ्यासयोगद्वारा उनलाई पाउन चाहनू।", "hi": "चित्त स्थिर न कर सकें तो अभ्यासयोग से उन्हें पाने की इच्छा करें।"}, "sutras": [{"n": "12.09", "d": "अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम् । अभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय", "t": "atha cittaṃ samādhātuṃ na śaknoṣi mayi sthiram । abhyāsayogena tato māmicchāptuṃ dhanañjaya", "flow": [{"k": "p", "d": "अथ चित्तं समाधातुं", "t": "atha cittaṃ samādhātuṃ", "n": 8, "words": [["अथ", "atha", "if", "यदि", "यदि"], ["चित्तम्", "cittam", "the mind", "चित्त", "चित्त"], ["समाधातुम्", "samādhātum", "to fix steadily", "स्थिर गर्न", "स्थिर करने"]]}, {"k": "p", "d": "न शक्नोषि मयि स्थिरम्", "t": "na śaknoṣi mayi sthiram", "n": 8, "words": [["न", "na", "not", "न", "नहीं"], ["शक्नोषि", "śaknoṣi", "you are able", "सक्छौ", "सकते हो"], ["मयि", "mayi", "on me", "ममा", "मुझमें"], ["स्थिरम्", "sthiram", "steadily", "स्थिर", "स्थिर"]]}, {"k": "p", "d": "अभ्यासयोगेन ततो", "t": "abhyāsayogena tato", "n": 8, "words": [["अभ्यासयोगेन", "abhyāsayogena", "by the yoga of practice", "अभ्यासयोगद्वारा", "अभ्यास-योग से"], ["ततः", "tataḥ", "then", "त्यसपछि", "तब"]]}, {"k": "p", "d": "मामिच्छाप्तुं धनञ्जय", "t": "māmicchāptuṃ dhanañjaya", "n": 8, "words": [["माम्", "mām", "me", "मलाई", "मुझे"], ["इच्छ", "iccha", "seek", "प्रयास गर", "प्रयास कर"], ["आप्तुम्", "āptum", "to reach", "पुग्न", "पहुँचना"], ["धनञ्जय", "dhanañjaya", "O Dhanañjaya", "हे धनञ्जय", "हे धनंजय"]]}], "lits": {"en": "If you cannot fix your mind steadily on me, then practise the yoga of repetition — seek to reach me by practice, O Dhanañjaya.", "ne": "यदि तिमी मन ममा स्थिर गर्न सक्दैनौ भने, हे धनञ्जय, अभ्यासयोगद्वारा — अभ्यासले मकहाँ पुग्ने प्रयास गर।", "hi": "यदि तू मन को मुझ में स्थिर नहीं कर सकता, तो हे धनंजय, अभ्यास-योग से — अभ्यास द्वारा मुझ तक पहुँचने का प्रयास कर।"}, "paras": {"en": "“If you cannot fix your mind on me steadily, then use repeated practice to reach me, Arjuna.”", "ne": "“यदि तिमी मन ममा स्थिर राख्न सक्दैनौ भने, बारम्बार अभ्यासले मकहाँ पुग्ने प्रयास गर, अर्जुन।”", "hi": "“यदि तू मन को मुझ पर स्थिर नहीं रख सकता, तो बार-बार के अभ्यास से मुझ तक पहुँचने का प्रयास कर, अर्जुन।”"}}]}, {"range": "12.10–12.10", "titles": {"en": "If not, work for my sake", "ne": "नसके मेरो निम्ति कर्म गर", "hi": "न हो तो मेरे लिए कर्म कर"}, "descs": {"en": "If even practice is too much, he should work for Kṛṣṇa’s sake and so reach perfection.", "ne": "अभ्यास पनि असम्भव भए कृष्णका लागि कर्म गर्नू, र सिद्धि पाउनू।", "hi": "अभ्यास भी असंभव हो तो कृष्ण के लिए कर्म करें, और सिद्धि पाएँ।"}, "sutras": [{"n": "12.10", "d": "अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव । मदर्थमपि कर्माणि कुर्वन्सिद्धिमवाप्स्यसि", "t": "abhyāse’pyasamartho’si matkarmaparamo bhava । madarthamapi karmāṇi kurvansiddhimavāpsyasi", "flow": [{"k": "p", "d": "अभ्यासेऽप्यसमर्थोऽसि", "t": "abhyāse’pyasamartho’si", "n": 8, "words": [["अभ्यासे", "abhyāse", "in practice", "अभ्यासमा", "अभ्यास में"], ["अपि", "api", "even", "पनि", "भी"], ["असमर्थः", "asamarthaḥ", "unable", "असमर्थ", "असमर्थ"], ["असि", "asi", "you are", "छौ", "हो"]]}, {"k": "p", "d": "मत्कर्मपरमो भव", "t": "matkarmaparamo bhava", "n": 8, "words": [["मत्कर्मपरमः", "matkarmaparamaḥ", "devoted to working for me", "मेरा निम्ति कर्ममा तत्पर", "मेरे लिए कर्म में तत्पर"], ["भव", "bhava", "be", "होऊ", "बनो"]]}, {"k": "p", "d": "मदर्थमपि कर्माणि", "t": "madarthamapi karmāṇi", "n": 8, "words": [["मदर्थम्", "madartham", "for my sake", "मेरै निम्ति", "मेरे लिए"], ["अपि", "api", "even", "पनि", "भी"], ["कर्माणि", "karmāṇi", "actions", "कर्महरू", "कर्म"]]}, {"k": "p", "d": "कुर्वन्सिद्धिमवाप्स्यसि", "t": "kurvansiddhimavāpsyasi", "n": 8, "words": [["कुर्वन्", "kurvan", "performing", "गर्दै", "करते हुए"], ["सिद्धिम्", "siddhim", "perfection", "सिद्धि", "सिद्धि"], ["अवाप्स्यसि", "avāpsyasi", "you will attain", "प्राप्त गर्नेछौ", "पा जाएगा"]]}], "lits": {"en": "If you are unable to practise even that, be devoted to working for me; even performing actions for my sake, you shall attain perfection.", "ne": "यदि त्यो पनि गर्न सक्दैनौ भने, मेरा निम्ति काम गर्नमा समर्पित होऊ; मेरै निम्ति कर्म गरे पनि तिमी सिद्धि पाउनेछौ।", "hi": "यदि तू वह भी नहीं कर सकता, तो मेरे लिए कर्म करने में समर्पित हो; मेरे ही लिए कर्म करके भी तू सिद्धि पा जाएगा।"}, "paras": {"en": "“If even that is beyond you, devote yourself to working for me — doing your work for my sake, you will reach perfection.”", "ne": "त्यति पनि नसके, मेरै काममा लागिपर। मेरा लागि गरेको कामले पनि तिमी पुग्नुपर्ने ठाउँमा पुग्छौ।", "hi": "“यदि वह भी सम्भव नहीं, तो मेरे लिए काम करने में लग जा — मेरे ही लिए कर्म करके भी तू सिद्धि तक पहुँचेगा।”"}}]}, {"range": "12.11–12.11", "titles": {"en": "If not even that, renounce the fruit", "ne": "त्यो पनि नसके फल त्याग", "hi": "वह भी न हो तो फल त्याग"}, "descs": {"en": "If even that is impossible, he should take refuge in Kṛṣṇa and give up the fruit of all actions.", "ne": "यो पनि नसके कृष्णको शरण लिई सबै कर्मको फल त्याग्नू।", "hi": "यह भी न हो सके तो कृष्ण की शरण लेकर सब कर्मों के फल का त्याग करें।"}, "sutras": [{"n": "12.11", "d": "अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः । सर्वकर्मफलत्यागं ततः कुरु यतात्मवान्", "t": "athaitadapyaśakto’si kartuṃ madyogamāśritaḥ । sarvakarmaphalatyāgaṃ tataḥ kuru yatātmavān", "flow": [{"k": "p", "d": "अथैतदप्यशक्तोऽसि", "t": "athaitadapyaśakto’si", "n": 8, "words": [["अथ", "atha", "if", "यदि", "यदि"], ["एतत्", "etat", "this", "यो", "यह"], ["अपि", "api", "even", "पनि", "भी"], ["अशक्तः", "aśaktaḥ", "unable", "असमर्थ", "असमर्थ"], ["असि", "asi", "you are", "छौ", "हो"]]}, {"k": "p", "d": "कर्तुं मद्योगमाश्रितः", "t": "kartuṃ madyogamāśritaḥ", "n": 8, "words": [["कर्तुम्", "kartum", "to do", "गर्न", "करना"], ["मद्योगम्", "madyogam", "my yoga", "मेरो योग", "मेरा योग"], ["आश्रितः", "āśritaḥ", "taking refuge in", "आश्रित", "आश्रित"]]}, {"k": "p", "d": "सर्वकर्मफलत्यागं", "t": "sarvakarmaphalatyāgaṃ", "n": 8, "words": [["सर्वकर्मफलत्यागम्", "sarvakarmaphalatyāgam", "the renunciation of the fruit of all actions", "सबै कर्मफलको त्याग", "सब कर्म-फलों का त्याग"]]}, {"k": "p", "d": "ततः कुरु यतात्मवान्", "t": "tataḥ kuru yatātmavān", "n": 8, "words": [["ततः", "tataḥ", "then", "त्यसपछि", "तब"], ["कुरु", "kuru", "do", "गर", "करो"], ["यतात्मवान्", "yatātmavān", "self-controlled", "आत्मसंयमी", "आत्म-संयमी"]]}], "lits": {"en": "If you cannot do even this, then, taking refuge in my yoga, renounce the fruit of all actions — with the self controlled.", "ne": "यदि यो पनि गर्न सक्दैनौ भने, मेरो योगको शरण लिएर, आत्मा संयत गरेर, सबै कर्मको फल त्याग।", "hi": "यदि यह भी नहीं कर सकता, तो मेरे योग की शरण लेकर, आत्मा को संयत करके, सब कर्मों का फल त्याग दे।"}, "paras": {"en": "“If you cannot do even that, then surrender the fruits of all your actions to me — with a self-controlled mind.”", "ne": "“यदि त्यो पनि गर्न सक्दैनौ भने, आत्म-संयमित मनले, आफ्ना सबै कर्मको फल मलाई समर्पण गर।”", "hi": "“यदि वह भी नहीं कर सकता, तो आत्म-संयमित मन से, अपने सब कर्मों का फल मुझे समर्पण कर दे।”"}}]}, {"range": "12.12–12.12", "titles": {"en": "Fruit-renunciation beats meditation; peace follows", "ne": "कर्मफल त्याग ध्यानभन्दा श्रेष्ठ; यसले शान्ति दिन्छ", "hi": "कर्मफल-त्याग ध्यान से श्रेष्ठ; इससे शान्ति मिलती है"}, "descs": {"en": "Knowledge is better than practice, meditation better than knowledge, and renunciation of fruit better than meditation, for peace follows at once.", "ne": "अभ्यासभन्दा ज्ञान, ज्ञानभन्दा ध्यान र ध्यानभन्दा कर्मफलत्याग श्रेष्ठ छ, किनकि त्यसपछि तुरुन्तै शान्ति मिल्छ।", "hi": "अभ्यास से ज्ञान, ज्ञान से ध्यान और ध्यान से कर्मफल-त्याग श्रेष्ठ है, क्योंकि उसके बाद तुरंत शांति मिलती है।"}, "sutras": [{"n": "12.12", "d": "श्रेयो हि ज्ञानमभ्यासात् ज्ञानाद्ध्यानं विशिष्यते । ध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम्", "t": "śreyo hi jñānamabhyāsāt jñānāddhyānaṃ viśiṣyate । dhyānātkarmaphalatyāgastyāgācchāntiranantaram", "flow": [{"k": "p", "d": "श्रेयो हि ज्ञानमभ्यासात्", "t": "śreyo hi jñānamabhyāsāt", "n": 8, "words": [["श्रेयः", "śreyaḥ", "better", "राम्रो", "अच्छा"], ["हि", "hi", "indeed", "नै", "ही"], ["ज्ञानम्", "jñānam", "knowledge", "ज्ञान", "ज्ञान"], ["अभ्यासात्", "abhyāsāt", "than practice", "अभ्यासभन्दा", "अभ्यास से"]]}, {"k": "p", "d": "ज्ञानाद्ध्यानं विशिष्यते", "t": "jñānāddhyānaṃ viśiṣyate", "n": 8, "words": [["ज्ञानात्", "jñānāt", "than knowledge", "ज्ञानभन्दा", "ज्ञान से"], ["ध्यानम्", "dhyānam", "meditation", "ध्यान", "ध्यान"], ["विशिष्यते", "viśiṣyate", "is better", "श्रेष्ठ हुन्छ", "श्रेष्ठ है"]]}, {"k": "p", "d": "ध्यानात्कर्मफलत्यागस्", "t": "dhyānātkarmaphalatyāgas", "n": 8, "words": [["ध्यानात्", "dhyānāt", "than meditation", "ध्यानभन्दा", "ध्यान से"], ["कर्मफलत्यागः", "karmaphalatyāgaḥ", "renunciation of the fruit of action", "कर्मफलको त्याग", "कर्म-फल का त्याग"]]}, {"k": "p", "d": "त्यागाच्छान्तिरनन्तरम्", "t": "tyāgācchāntiranantaram", "n": 8, "words": [["त्यागात्", "tyāgāt", "from renunciation", "त्यागबाट", "त्याग से"], ["शान्तिः", "śāntiḥ", "peace", "शान्ति", "शान्ति"], ["अनन्तरम्", "anantaram", "immediately", "तुरुन्तै", "तुरन्त"]]}], "lits": {"en": "Better indeed is knowledge than practice; better than knowledge is meditation; better than meditation is renunciation of the fruit of action — for from renunciation comes peace, immediately.", "ne": "अभ्यासभन्दा ज्ञान राम्रो; ज्ञानभन्दा ध्यान राम्रो; ध्यानभन्दा कर्मफलत्याग राम्रो — किनकि त्यागबाट तुरुन्तै शान्ति मिल्छ।", "hi": "अभ्यास से ज्ञान अच्छा है; ज्ञान से ध्यान अच्छा है; ध्यान से कर्म-फल-त्याग अच्छा है — क्योंकि त्याग से तुरन्त शान्ति मिलती है।"}, "paras": {"en": "“Knowledge is better than practice; meditation is better than knowledge; and better still is renouncing the fruits of work — for that brings peace at once.”", "ne": "अभ्यासभन्दा बुझाइ ठूलो, बुझाइभन्दा ध्यान; ती सबैभन्दा माथि — फलको आस छोड्नु। आस छुट्यो कि शान्ति त्यहीँ।", "hi": "अभ्यास से समझ बेहतर, समझ से ध्यान बेहतर; पर सबसे बेहतर है नतीजे की चाह छोड़ देना — वहीं से चैन तुरन्त शुरू होता है।"}}]}]}, {"range": "12.13–12.16", "titles": {"en": "Compassion and self-mastery make a dear devotee", "ne": "करुणा र संयमले प्रिय भक्त बनाउँछन्", "hi": "करुणा और संयम प्रिय भक्त बनाते हैं"}, "descs": {"en": "The dear devotee hates no being, is compassionate and steady, neither disturbs the world nor is disturbed by it, free of expectation, and renounces all undertakings.", "ne": "प्रिय भक्तले कसैलाई द्वेष गर्दैन, करुणाशील र स्थिर हुन्छ। उसले लोकलाई विचलित गर्दैन, लोकबाट विचलित हुँदैन, अपेक्षारहित हुन्छ र सबै आरम्भ त्याग्छ।", "hi": "प्रिय भक्त किसी से द्वेष नहीं करता, करुणाशील और स्थिर होता है। वह लोक को विचलित नहीं करता, लोक से विचलित नहीं होता, अपेक्षारहित रहता है और सभी आरंभों का त्यागी होता है।"}, "parts": [{"range": "12.13–12.13", "titles": {"en": "Hating no being, friendly and compassionate", "ne": "कसैप्रति द्वेष नराख्ने, मैत्र र करुण", "hi": "किसी से द्वेष न रखने वाला, मैत्र और करुण"}, "descs": {"en": "The portrait of the dear devotee begins: hating no being, friendly, compassionate, free of ‘mine’ and ego…", "ne": "प्रिय भक्तको चित्रण सुरु: कसैसँग द्वेष नगर्ने, मैत्री, करुणावान्, ममत्व र अहङ्कारविना…", "hi": "प्रिय भक्त का चित्रण आरंभ: किसी से द्वेष न करने वाला, मैत्रीपूर्ण, करुणावान, ममता और अहंकार से रहित…"}, "sutras": [{"n": "12.13", "d": "अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च । निर्ममो निरहङ्कारः समदुःखसुखः क्षमी", "t": "adveṣṭā sarvabhūtānāṃ maitraḥ karuṇa eva ca । nirmamo nirahaṅkāraḥ samaduḥkhasukhaḥ kṣamī", "flow": [{"k": "p", "d": "अद्वेष्टा सर्वभूतानां", "t": "adveṣṭā sarvabhūtānāṃ", "n": 8, "words": [["अद्वेष्टा", "adveṣṭā", "not hating", "द्वेष नगर्ने", "द्वेष न करने वाला"], ["सर्वभूतानाम्", "sarvabhūtānām", "of all beings", "सबै प्राणीको", "सब प्राणियों का"]]}, {"k": "p", "d": "मैत्रः करुण एव च", "t": "maitraḥ karuṇa eva ca", "n": 8, "words": [["मैत्रः", "maitraḥ", "friendly", "मित्रवत्", "मित्र-भाव वाला"], ["करुणः", "karuṇaḥ", "compassionate", "करुणामय", "करुणामय"], ["एव", "eva", "indeed", "नै", "ही"], ["च", "ca", "and", "र", "और"]]}, {"k": "p", "d": "निर्ममो निरहङ्कारः", "t": "nirmamo nirahaṅkāraḥ", "n": 8, "words": [["निर्ममः", "nirmamaḥ", "free from possessiveness", "निर्मम", "निर्मम"], ["निरहङ्कारः", "nirahaṅkāraḥ", "free from ego", "अहंकाररहित", "अहंकार-रहित"]]}, {"k": "p", "d": "समदुःखसुखः क्षमी", "t": "samaduḥkhasukhaḥ kṣamī", "n": 8, "words": [["समदुःखसुखः", "samaduḥkhasukhaḥ", "equal in pleasure and pain", "सुख-दुःखमा समान", "सुख-दुःख में समान"], ["क्षमी", "kṣamī", "forgiving", "क्षमाशील", "क्षमाशील"]]}], "lits": {"en": "He who hates no being, is friendly and compassionate, free from possessiveness and ego, equal in pleasure and pain, forgiving —", "ne": "जसले कुनै प्राणीलाई घृणा गर्दैन, मित्रवत् र दयालु छ, ममता र अहंकारबाट मुक्त छ, सुख-दुःखमा समान छ, क्षमाशील छ —", "hi": "जो किसी प्राणी से द्वेष नहीं करता, मित्र-भाव और करुणा रखता है, ममता और अहंकार से मुक्त है, सुख-दुःख में समान है, क्षमाशील है —"}, "paras": {"en": "“One who hates no one, is kind and compassionate, free of 'mine' and 'I', even in joy and sorrow, patient —”", "ne": "“जो कसैसँग घृणा गर्दैन, दयालु र करुणामय छ, 'मेरो' र 'म' बाट मुक्त छ, सुख-दुःखमा एकनास छ, धैर्यवान् छ —”", "hi": "“जो किसी से घृणा नहीं करता, दयालु और करुणामय है, 'मेरा' और 'मैं' से मुक्त है, सुख-दुःख में एक-सा है, धैर्यवान् है —”"}}]}, {"range": "12.14–12.14", "titles": {"en": "Ever content, resolved, given to me", "ne": "सदा सन्तुष्ट, दृढ, ममा अर्पित", "hi": "सदा सन्तुष्ट, दृढ़, मुझमें अर्पित"}, "descs": {"en": "…ever content, self-controlled, firm in resolve, with mind and intellect offered to Kṛṣṇa.", "ne": "…सधैं सन्तुष्ट, संयमी, दृढ निश्चयी, मन-बुद्धि कृष्णमा अर्पित गरेको।", "hi": "…सदा संतुष्ट, संयमी, दृढ़ निश्चयी, मन-बुद्धि कृष्ण को अर्पित किए हुए।"}, "sutras": [{"n": "12.14", "d": "सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः । मय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः", "t": "santuṣṭaḥ satataṃ yogī yatātmā dṛḍhaniścayaḥ । mayyarpitamanobuddhiryo madbhaktaḥ sa me priyaḥ", "flow": [{"k": "p", "d": "सन्तुष्टः सततं योगी", "t": "santuṣṭaḥ satataṃ yogī", "n": 8, "words": [["सन्तुष्टः", "santuṣṭaḥ", "content", "सन्तुष्ट", "संतुष्ट"], ["सततम्", "satatam", "always", "सधैँ", "सदा"], ["योगी", "yogī", "the yogi", "योगी", "योगी"]]}, {"k": "p", "d": "यतात्मा दृढनिश्चयः", "t": "yatātmā dṛḍhaniścayaḥ", "n": 8, "words": [["यतात्मा", "yatātmā", "self-controlled", "आत्मसंयमी", "आत्म-संयमी"], ["दृढनिश्चयः", "dṛḍhaniścayaḥ", "of firm resolve", "दृढ निश्चयको", "दृढ़ निश्चय वाला"]]}, {"k": "p", "d": "मय्यर्पितमनोबुद्धिर्", "t": "mayyarpitamanobuddhir", "n": 8, "words": [["मयि", "mayi", "to me", "ममा", "मुझमें"], ["अर्पित", "arpita", "offered", "अर्पण गरिएको", "अर्पित"], ["मनोबुद्धिः", "manobuddhiḥ", "mind and intellect", "मन र बुद्धि", "मन और बुद्धि"]]}, {"k": "p", "d": "यो मद्भक्तः स मे प्रियः", "t": "yo madbhaktaḥ sa me priyaḥ", "n": 8, "words": [["यः", "yaḥ", "who", "जो", "जो"], ["मद्भक्तः", "madbhaktaḥ", "my devotee", "मेरो भक्त", "मेरा भक्त"], ["सः", "saḥ", "he", "ऊ", "वह"], ["मे", "me", "to me", "मलाई", "मुझे"], ["प्रियः", "priyaḥ", "dear", "प्रिय", "प्रिय"]]}], "lits": {"en": "— ever content, a yogi, self-controlled, of firm resolve, mind and intellect offered to me — that devotee of mine is dear to me.", "ne": "— सधैं सन्तुष्ट, योगी, आत्मसंयमी, दृढ संकल्प भएको, मन र बुद्धि ममा अर्पण गरेको — त्यो मेरो भक्त मलाई प्रिय छ।", "hi": "— सदा संतुष्ट, योगी, आत्म-संयमी, दृढ़ संकल्प वाला, मन और बुद्धि मुझ में अर्पण किए — वह मेरा भक्त मुझे प्रिय है।"}, "paras": {"en": "“— always content, self-mastered, resolute, with mind and heart given to me — such a devotee is dear to me.”", "ne": "“— सधैं सन्तोषी, आत्मविजयी, संकल्पवान्, मन र हृदय मलाई दिएको — यस्तो भक्त मलाई प्रिय छ।”", "hi": "“— सदा संतोषी, आत्म-विजयी, संकल्पवान्, मन और हृदय मुझे दिए — ऐसा भक्त मुझे प्रिय है।”"}}]}, {"range": "12.15–12.15", "titles": {"en": "Neither disturbs the world nor is disturbed by it", "ne": "संसारलाई न विचलित पार्ने, संसारबाट न विचलित हुने", "hi": "न जगत को विचलित करे, न उससे विचलित हो"}, "descs": {"en": "He who does not disturb the world and is not disturbed by it, free from joy, anger, fear and agitation, is dear to him.", "ne": "जसले संसारलाई उद्विग्न पार्दैन, र संसारले जसलाई उद्विग्न पार्दैन; हर्ष, क्रोध, भय र उद्वेगबाट मुक्त, ऊ प्रिय छ।", "hi": "जो संसार को उद्विग्न नहीं करता और संसार जिसे उद्विग्न नहीं करता; हर्ष, क्रोध, भय और उद्वेग से मुक्त, वह प्रिय है।"}, "sutras": [{"n": "12.15", "d": "यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः । हर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः", "t": "yasmānnodvijate loko lokānnodvijate ca yaḥ । harṣāmarṣabhayodvegairmukto yaḥ sa ca me priyaḥ", "flow": [{"k": "p", "d": "यस्मान्नोद्विजते लोको", "t": "yasmānnodvijate loko", "n": 8, "words": [["यस्मात्", "yasmāt", "by whom", "जसद्वारा", "जिससे"], ["न", "na", "not", "न", "नहीं"], ["उद्विजते", "udvijate", "is agitated", "विचलित हुन्छ", "व्याकुल होता है"], ["लोकः", "lokaḥ", "the world", "लोक", "लोक"]]}, {"k": "p", "d": "लोकान्नोद्विजते च यः", "t": "lokānnodvijate ca yaḥ", "n": 8, "words": [["लोकात्", "lokāt", "by the world", "संसारबाट", "संसार से"], ["न", "na", "not", "न", "नहीं"], ["उद्विजते", "udvijate", "is agitated", "विचलित हुन्छ", "व्याकुल होता है"], ["च", "ca", "and", "र", "और"], ["यः", "yaḥ", "who", "जो", "जो"]]}, {"k": "p", "d": "हर्षामर्षभयोद्वेगैर्", "t": "harṣāmarṣabhayodvegair", "n": 8, "words": [["हर्ष", "harṣa", "joy", "हर्ष", "हर्ष"], ["अमर्ष", "amarṣa", "anger", "क्रोध", "क्रोध"], ["भय", "bhaya", "fear", "भय", "भय"], ["उद्वेगैः", "udvegaiḥ", "anxiety", "चिन्ताहरूले", "चिन्ताओं से"]]}, {"k": "p", "d": "मुक्तो यः स च मे प्रियः", "t": "mukto yaḥ sa ca me priyaḥ", "n": 8, "words": [["मुक्तः", "muktaḥ", "freed from", "मुक्त", "मुक्त"], ["यः", "yaḥ", "who", "जो", "जो"], ["सः", "saḥ", "he", "ऊ", "वह"], ["च", "ca", "and", "र", "और"], ["मे", "me", "to me", "मलाई", "मुझे"], ["प्रियः", "priyaḥ", "dear", "प्रिय", "प्रिय"]]}], "lits": {"en": "He by whom the world is not disturbed, and who is not disturbed by the world — freed from joy, anger, fear and anxiety — he is dear to me.", "ne": "जसद्वारा संसार विचलित हुँदैन, र जो संसारले विचलित हुँदैन — हर्ष, क्रोध, भय र चिन्ताबाट मुक्त — ऊ मलाई प्रिय छ।", "hi": "जिससे संसार विचलित नहीं होता, और जो संसार से विचलित नहीं होता — हर्ष, क्रोध, भय और चिन्ता से मुक्त — वह मुझे प्रिय है।"}, "paras": {"en": "“One who disturbs no one and is disturbed by no one, free from joy, anger, fear, and worry — he is dear to me.”", "ne": "जसबाट कसैलाई पीर पर्दैन, र जो आफैँ कसैबाट पीरोलिँदैन; हर्ष, रिस, डर र सन्तापले नछोएको — त्यो मान्छे मलाई प्यारो छ।", "hi": "जिससे किसी को तकलीफ़ नहीं होती, और जिसे किसी से तकलीफ़ नहीं होती; जो न फूलता है, न भड़कता, न डरता, न घबराता — वह मुझे प्यारा है।"}}]}, {"range": "12.16–12.16", "titles": {"en": "Unattached, pure, capable, untroubled", "ne": "अनासक्त, शुचि, दक्ष, उदासीन", "hi": "अनासक्त, शुचि, दक्ष, उदासीन"}, "descs": {"en": "Unattached, pure, capable, impartial, untroubled and giving up all undertakings, he is dear.", "ne": "अनासक्त, शुद्ध, दक्ष, निष्पक्ष, चिन्तारहित र सबै आरम्भ त्यागेको भक्त प्रिय छ।", "hi": "अनासक्त, शुद्ध, दक्ष, निष्पक्ष, चिंतारहित और सब आरंभ त्यागने वाला भक्त प्रिय है।"}, "sutras": [{"n": "12.16", "d": "अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः । सर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः", "t": "anapekṣaḥ śucirdakṣa udāsīno gatavyathaḥ । sarvārambhaparityāgī yo madbhaktaḥ sa me priyaḥ", "flow": [{"k": "p", "d": "अनपेक्षः शुचिर्दक्ष", "t": "anapekṣaḥ śucirdakṣa", "n": 8, "words": [["अनपेक्षः", "anapekṣaḥ", "unattached, indifferent", "आसक्तिरहित", "आसक्ति-रहित"], ["शुचिः", "śuciḥ", "pure", "शुद्ध", "शुद्ध"], ["दक्षः", "dakṣaḥ", "capable", "दक्ष", "दक्ष"]]}, {"k": "p", "d": "उदासीनो गतव्यथः", "t": "udāsīno gatavyathaḥ", "n": 8, "words": [["उदासीनः", "udāsīnaḥ", "neutral, indifferent", "उदासीन", "उदासीन"], ["गतव्यथः", "gatavyathaḥ", "free from anxiety", "व्यथारहित", "व्यथा-रहित"]]}, {"k": "p", "d": "सर्वारम्भपरित्यागी", "t": "sarvārambhaparityāgī", "n": 8, "words": [["सर्वारम्भपरित्यागी", "sarvārambhaparityāgī", "renouncing all undertakings", "सबै आरम्भ त्याग्ने", "सब आरम्भों का त्यागी"]]}, {"k": "p", "d": "यो मद्भक्तः स मे प्रियः", "t": "yo madbhaktaḥ sa me priyaḥ", "n": 8, "words": [["यः", "yaḥ", "who", "जो", "जो"], ["मद्भक्तः", "madbhaktaḥ", "my devotee", "मेरो भक्त", "मेरा भक्त"], ["सः", "saḥ", "he", "ऊ", "वह"], ["मे", "me", "to me", "मलाई", "मुझे"], ["प्रियः", "priyaḥ", "dear", "प्रिय", "प्रिय"]]}], "lits": {"en": "He who is unattached, pure, capable, indifferent, free from anxiety, renouncing all undertakings — that devotee of mine is dear to me.", "ne": "जो आसक्तिरहित, शुद्ध, दक्ष, उदासीन, चिन्तारहित, सबै आरम्भ त्याग्ने — त्यो मेरो भक्त मलाई प्रिय छ।", "hi": "जो आसक्ति-रहित, शुद्ध, दक्ष, उदासीन, चिन्ता-रहित, सब आरम्भों का त्यागी — वह मेरा भक्त मुझे प्रिय है।"}, "paras": {"en": "“One who is detached, pure, skilled, neutral, worry-free, and gives up all selfish projects — that devotee is dear to me.”", "ne": "“जो आसक्तिरहित, शुद्ध, निपुण, तटस्थ, चिन्तामुक्त, र सबै स्वार्थी परियोजना छोड्ने — त्यो भक्त मलाई प्रिय छ।”", "hi": "“जो आसक्ति-रहित, शुद्ध, निपुण, तटस्थ, चिन्ता-मुक्त, और सब स्वार्थी परियोजनाओं को छोड़ने वाला — वह भक्त मुझे प्रिय है।”"}}]}]}, {"range": "12.17–12.20", "titles": {"en": "Evenness and faithful devotion complete the path", "ne": "समभाव र श्रद्धाले भक्तिमार्ग पूरा हुन्छ", "hi": "समभाव और श्रद्धा भक्तिमार्ग पूर्ण करते हैं"}, "descs": {"en": "Equal through praise and blame, friend and foe, the devotee remains content and steady. Those who follow this immortal dharma with faith are exceedingly dear.", "ne": "प्रशंसा-निन्दा, मित्र-शत्रु र द्वन्द्वमा समभाव राखेर भक्त सन्तुष्ट र स्थिर रहन्छ। यो अमृतधर्म श्रद्धाले पालना गर्नेहरू अत्यन्त प्रिय छन्।", "hi": "प्रशंसा-निंदा, मित्र-शत्रु और द्वंद्वों में समभाव से भक्त संतुष्ट और स्थिर रहता है। इस अमृतधर्म को श्रद्धा से मानने वाले अत्यंत प्रिय हैं।"}, "parts": [{"range": "12.17–12.17", "titles": {"en": "Neither rejoicing nor hating", "ne": "न हर्ष, न द्वेष", "hi": "न हर्ष, न द्वेष"}, "descs": {"en": "He neither rejoices nor hates, neither grieves nor craves, and has let go of good and evil.", "ne": "जसले न हर्षित हुन्छ न द्वेष गर्छ, न शोक गर्छ न चाहना, र शुभ-अशुभ छोडेको छ।", "hi": "जो न हर्षित होता है न द्वेष करता है, न शोक करता है न चाह, और शुभ-अशुभ छोड़ चुका है।"}, "sutras": [{"n": "12.17", "d": "यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति । शुभाशुभपरित्यागी भक्तिमान्यः स मे प्रियः", "t": "yo na hṛṣyati na dveṣṭi na śocati na kāṅkṣati । śubhāśubhaparityāgī bhaktimānyaḥ sa me priyaḥ", "flow": [{"k": "p", "d": "यो न हृष्यति न द्वेष्टि", "t": "yo na hṛṣyati na dveṣṭi", "n": 8, "words": [["यः", "yaḥ", "who", "जो", "जो"], ["न", "na", "neither", "न", "नहीं"], ["हृष्यति", "hṛṣyati", "rejoices", "रम्छ", "हर्षित होता है"], ["न", "na", "nor", "न", "नहीं"], ["द्वेष्टि", "dveṣṭi", "hates", "घृणा गर्दछ", "द्वेष करता है"]]}, {"k": "p", "d": "न शोचति न काङ्क्षति", "t": "na śocati na kāṅkṣati", "n": 8, "words": [["न", "na", "neither", "न", "नहीं"], ["शोचति", "śocati", "grieves", "शोक गर्छ", "शोक करता है"], ["न", "na", "nor", "न", "नहीं"], ["काङ्क्षति", "kāṅkṣati", "desires", "इच्छा गर्छ", "इच्छा करता है"]]}, {"k": "p", "d": "शुभाशुभपरित्यागी", "t": "śubhāśubhaparityāgī", "n": 8, "words": [["शुभाशुभपरित्यागी", "śubhāśubhaparityāgī", "renouncing good and evil", "असल-नराम्रो त्याग्ने", "शुभ-अशुभ का त्यागी"]]}, {"k": "p", "d": "भक्तिमान्यः स मे प्रियः", "t": "bhaktimānyaḥ sa me priyaḥ", "n": 8, "words": [["भक्तिमान्", "bhaktimān", "devoted", "भक्त", "भक्त"], ["यः", "yaḥ", "who", "जो", "जो"], ["सः", "saḥ", "he", "ऊ", "वह"], ["मे", "me", "to me", "मलाई", "मुझे"], ["प्रियः", "priyaḥ", "dear", "प्रिय", "प्रिय"]]}], "lits": {"en": "He who neither rejoices nor hates, neither grieves nor desires, renouncing good and evil — that devoted one is dear to me.", "ne": "जो न रम्छ न घृणा गर्छ, न शोक गर्छ न इच्छा राख्छ, असल र नराम्रो दुवै त्याग्ने — त्यो भक्त मलाई प्रिय छ।", "hi": "जो न रमता है न घृणा करता है, न शोक करता है न इच्छा रखता है, शुभ और अशुभ दोनों को त्यागने वाला — वह भक्त मुझे प्रिय है।"}, "paras": {"en": "“One who neither delights nor despairs, neither mourns nor craves, letting go of good and evil — such a devotee is dear to me.”", "ne": "“जो न हर्षित हुन्छ न निराश, न शोक गर्छ न लालसा, असल-नराम्रो दुवै छोड्ने — यस्तो भक्त मलाई प्रिय छ।”", "hi": "“जो न हर्षित होता है न निराश, न शोक करता है न लालसा, शुभ-अशुभ दोनों छोड़ने वाला — ऐसा भक्त मुझे प्रिय है।”"}}]}, {"range": "12.18–12.18", "titles": {"en": "Equal to friend and foe, honour and dishonour", "ne": "शत्रु-मित्र, मान-अपमानमा समान", "hi": "शत्रु-मित्र, मान-अपमान में समान"}, "descs": {"en": "Equal to friend and foe, honour and dishonour, cold and heat, pleasure and pain, and free from attachment…", "ne": "शत्रु-मित्र, मान-अपमान, शीत-उष्ण, सुख-दुःखमा सम र आसक्तिरहित…", "hi": "शत्रु-मित्र, मान-अपमान, सर्दी-गर्मी, सुख-दुःख में सम और आसक्तिरहित…"}, "sutras": [{"n": "12.18", "d": "समः शत्रौ च मित्रे च तथा मानापमानयोः । शीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः", "t": "samaḥ śatrau ca mitre ca tathā mānāpamānayoḥ । śītoṣṇasukhaduḥkheṣu samaḥ saṅgavivarjitaḥ", "flow": [{"k": "p", "d": "समः शत्रौ च मित्रे च", "t": "samaḥ śatrau ca mitre ca", "n": 8, "words": [["समः", "samaḥ", "equal", "समान", "समान"], ["शत्रौ", "śatrau", "to an enemy", "शत्रुमा", "शत्रु में"], ["च", "ca", "and", "र", "और"], ["मित्रे", "mitre", "to a friend", "मित्रमा", "मित्र में"], ["च", "ca", "and", "र", "और"]]}, {"k": "p", "d": "तथा मानापमानयोः", "t": "tathā mānāpamānayoḥ", "n": 8, "words": [["तथा", "tathā", "so", "त्यसरी", "वैसे ही"], ["मान", "māna", "honour", "मान", "मान"], ["अपमानयोः", "apamānayoḥ", "and dishonour", "अपमानमा", "अपमान में"]]}, {"k": "p", "d": "शीतोष्णसुखदुःखेषु", "t": "śītoṣṇasukhaduḥkheṣu", "n": 8, "words": [["शीतोष्ण", "śītoṣṇa", "cold and heat", "जाडो-गर्मी", "सर्दी-गर्मी"], ["सुखदुःखेषु", "sukhaduḥkheṣu", "in pleasure and pain", "सुख-दुःखमा", "सुख-दुःख में"]]}, {"k": "p", "d": "समः सङ्गविवर्जितः", "t": "samaḥ saṅgavivarjitaḥ", "n": 8, "words": [["समः", "samaḥ", "equal", "समान", "समान"], ["सङ्गविवर्जितः", "saṅgavivarjitaḥ", "free from attachment", "आसक्तिरहित", "आसक्ति-रहित"]]}], "lits": {"en": "Equal to friend and foe, to honour and dishonour, to cold and heat, pleasure and pain, free from attachment —", "ne": "मित्र र शत्रु, मान र अपमान, जाडो र गर्मी, सुख र दुःखमा समान, आसक्तिरहित —", "hi": "मित्र और शत्रु, मान और अपमान, सर्दी और गर्मी, सुख और दुःख में समान, आसक्ति-रहित —"}, "paras": {"en": "“Equal toward friend and enemy, praise and blame, cold and heat, joy and sorrow, free from clinging —”", "ne": "“मित्र र शत्रु, प्रशंसा र निन्दा, जाडो-गर्मी, सुख-शोकमा समान, आसक्तिबाट मुक्त —”", "hi": "“मित्र और शत्रु, प्रशंसा और निन्दा, सर्दी-गर्मी, सुख-शोक में समान, आसक्ति से मुक्त —”"}}]}, {"range": "12.19–12.19", "titles": {"en": "Silent, satisfied with anything", "ne": "मौन, जे पाए पनि सन्तुष्ट", "hi": "मौन, जो मिले उसी में सन्तुष्ट"}, "descs": {"en": "…silent, content with anything, homeless, steady in mind and full of devotion — such a person is dear.", "ne": "…मौनी, जे पाए पनि सन्तुष्ट, अनिकेत, स्थिरमति र भक्तिमान् — यस्तो मानिस प्रिय हो।", "hi": "…मौनी, जो मिले उसी में संतुष्ट, अनिकेत, स्थिरमति और भक्तिमान — ऐसा मनुष्य प्रिय है।"}, "sutras": [{"n": "12.19", "d": "तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येन केनचित् । अनिकेतः स्थिरमतिर्भक्तिमान्मे प्रियो नरः", "t": "tulyanindāstutirmaunī santuṣṭo yena kenacit । aniketaḥ sthiramatirbhaktimānme priyo naraḥ", "flow": [{"k": "p", "d": "तुल्यनिन्दास्तुतिर्मौनी", "t": "tulyanindāstutirmaunī", "n": 8, "words": [["तुल्य", "tulya", "equal in", "समान", "समान"], ["निन्दा", "nindā", "blame", "निन्दा", "निन्दा"], ["स्तुतिः", "stutiḥ", "and praise", "स्तुति", "स्तुति"], ["मौनी", "maunī", "silent", "मौनी", "मौनी"]]}, {"k": "p", "d": "सन्तुष्टो येन केनचित्", "t": "santuṣṭo yena kenacit", "n": 8, "words": [["सन्तुष्टः", "santuṣṭaḥ", "content", "सन्तुष्ट", "संतुष्ट"], ["येन", "yena", "with whatever", "जसद्वारा", "जिससे"], ["केनचित्", "kenacit", "anything", "केही", "किसी से"]]}, {"k": "p", "d": "अनिकेतः स्थिरमतिर्", "t": "aniketaḥ sthiramatir", "n": 8, "words": [["अनिकेतः", "aniketaḥ", "homeless", "घरबारविहीन", "घर-रहित"], ["स्थिरमतिः", "sthiramatiḥ", "of steady mind", "स्थिर मन", "स्थिर मन"]]}, {"k": "p", "d": "भक्तिमान्मे प्रियो नरः", "t": "bhaktimānme priyo naraḥ", "n": 8, "words": [["भक्तिमान्", "bhaktimān", "devoted", "भक्त", "भक्त"], ["मे", "me", "to me", "मलाई", "मुझे"], ["प्रियः", "priyaḥ", "dear", "प्रिय", "प्रिय"], ["नरः", "naraḥ", "man", "मानिस", "मनुष्य"]]}], "lits": {"en": "— equal in blame and praise, silent, content with anything, homeless, of steady mind, full of devotion — that man is dear to me.", "ne": "— निन्दा र स्तुतिमा समान, मौन, जे पनि पाए त्यसैमा सन्तुष्ट, घरबारविहीन, स्थिर मन भएको, भक्तिले भरिएको — त्यो मानिस मलाई प्रिय छ।", "hi": "— निन्दा और स्तुति में समान, मौन, जो कुछ मिले उसी में संतुष्ट, गृह-रहित, स्थिर मन वाला, भक्ति से भरा — वह मनुष्य मुझे प्रिय है।"}, "paras": {"en": "“— the same in blame and praise, silent, satisfied with whatever comes, unattached to place, steady-minded, devoted — such a person is dear to me.”", "ne": "“— निन्दा र प्रशंसामा समान, मौन, जे आइपर्छ त्यसैमा सन्तुष्ट, ठाउँप्रति आसक्तिरहित, स्थिर मन, समर्पित — यस्तो व्यक्ति मलाई प्रिय छ।”", "hi": "“— निन्दा और प्रशंसा में समान, मौन, जो मिले उसी में संतुष्ट, स्थान से आसक्ति-रहित, स्थिर मन, समर्पित — ऐसा व्यक्ति मुझे प्रिय है।”"}}]}, {"range": "12.20–12.20", "titles": {"en": "They who follow this immortal dharma are dearest", "ne": "यो अमृत धर्म पछ्याउनेहरू मलाई अत्यन्त प्रिय", "hi": "इस अमृत धर्म का पालन करने वाले मुझे अत्यन्त प्रिय"}, "descs": {"en": "The chapter closes: those who faithfully follow this immortal dharma, making him their supreme goal, are dearest to him.", "ne": "अध्यायको अन्त्य: श्रद्धाले यो अमृतमय धर्म पालन गरी कृष्णलाई परम मान्नेहरू उनका अत्यन्त प्रिय हुन्।", "hi": "अध्याय का समापन: श्रद्धा से इस अमृतमय धर्म का पालन करके कृष्ण को परम मानने वाले उन्हें अत्यंत प्रिय हैं।"}, "sutras": [{"n": "12.20", "d": "ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते । श्रद्दधाना मत्परमाः भक्तास्तेऽतीव मे प्रियाः", "t": "ye tu dharmyāmṛtamidaṃ yathoktaṃ paryupāsate । śraddadhānā matparamāḥ bhaktāste’tīva me priyāḥ", "flow": [{"k": "p", "d": "ये तु धर्म्यामृतमिदं", "t": "ye tu dharmyāmṛtamidaṃ", "n": 8, "words": [["ये", "ye", "those who", "जो", "जो"], ["तु", "tu", "but", "तर", "पर"], ["धर्म्य", "dharmya", "righteous, immortal", "धार्मिक", "धार्मिक"], ["अमृतम्", "amṛtam", "nectar", "अमृत", "अमृत"], ["इदम्", "idam", "this", "यो", "यह"]]}, {"k": "p", "d": "यथोक्तं पर्युपासते", "t": "yathoktaṃ paryupāsate", "n": 8, "words": [["यथोक्तम्", "yathoktam", "as declared", "भनिएअनुसार", "कहे अनुसार"], ["पर्युपासते", "paryupāsate", "follow", "अनुसरण गर्छन्", "अनुसरण करते हैं"]]}, {"k": "p", "d": "श्रद्दधाना मत्परमाः", "t": "śraddadhānā matparamāḥ", "n": 8, "words": [["श्रद्दधानाः", "śraddadhānāḥ", "having faith", "श्रद्धा गर्नेहरू", "श्रद्धा रखने वाले"], ["मत्परमाः", "matparamāḥ", "making me the supreme goal", "मलाई परम मान्ने", "मुझे परम मानने वाले"]]}, {"k": "p", "d": "भक्तास्तेऽतीव मे प्रियाः", "t": "bhaktāste’tīva me priyāḥ", "n": 8, "words": [["भक्ताः", "bhaktāḥ", "devotees", "भक्तहरू", "भक्त"], ["ते", "te", "they", "तिनीहरू", "वे"], ["अतीव", "atīva", "exceedingly", "अत्यन्त", "अत्यन्त"], ["मे", "me", "to me", "मलाई", "मुझे"], ["प्रियाः", "priyāḥ", "dear", "प्रियहरू", "प्रिय"]]}], "lits": {"en": "But those who follow this immortal dharma, as declared, with faith, making me the supreme goal — those devotees are exceedingly dear to me.", "ne": "तर जसले यो अमृत धर्मलाई, बताइएअनुसार, श्रद्धाले, मलाई परम लक्ष्य बनाएर अनुसरण गर्छन् — ती भक्तहरू मलाई अत्यन्त प्रिय छन्।", "hi": "किन्तु जो इस अमृत धर्म का, कहे अनुसार, श्रद्धा से, मुझे परम लक्ष्य बनाकर अनुसरण करते हैं — वे भक्त मुझे अत्यन्त प्रिय हैं।"}, "paras": {"en": "“But those who follow this deathless dharma with faith, holding me as the highest goal — such devotees are most dear to me of all.”", "ne": "“तर जसले यो अमर धर्मलाई श्रद्धाले, मलाई सर्वोच्च लक्ष्य मानेर पछ्याउँछन् — यस्ता भक्तहरू सबैभन्दा प्रिय छन्।”", "hi": "“किन्तु जो इस अमर धर्म का श्रद्धा से, मुझे सर्वोच्च लक्ष्य मानकर अनुसरण करते हैं — ऐसे भक्त सबसे अधिक प्रिय हैं।”"}}]}]}], "colophon": {"deva": "ॐ तत्सदिति श्रीमद्भगवद्गीतासूपनिषत्सु ब्रह्मविद्यायां योगशास्त्रे श्रीकृष्णार्जुनसंवादे भक्तियोगो नाम द्वादशोऽध्यायः ॥ १२ ॥", "iast": "oṃ tatsaditi śrīmadbhagavadgītāsūpaniṣatsu brahmavidyāyāṃ yogaśāstre śrīkṛṣṇārjunasaṃvāde bhaktiyogo nāma dvādaśo’dhyāyaḥ ।। 12।।"}};
